<script>(()=>{const website=document.getElementById('website'),button=document.getElementById('research-website'),status=document.getElementById('enrichment-status'),review=document.getElementById('enrichment-review'),token=document.querySelector('meta[name="csrf-token"]').content,startUrl=@json(route('organization.enrich')),statusUrl=@json(route('organization.enrichment.status'));let lastQueued='',timer=null;const lists=new Set(['program_areas','populations_served','needs','keywords']);function valid(){try{const url=new URL(website.value);return ['http:','https:'].includes(url.protocol)}catch{return false}}function fill(profile){Object.entries(profile||{}).forEach(([key,value])=>{const field=document.getElementById(key);if(!field||value===null)return;const blank=!field.value||(key==='nonprofit_status'&&field.value==='unknown');if(blank)field.value=Array.isArray(value)?value.join(lists.has(key)?'\n':', '):value})}async function poll(){const response=await fetch(statusUrl,{headers:{Accept:'application/json'},credentials:'same-origin'}),data=await response.json();status.textContent=data.message||'Website research is running…';if(['queued','running'].includes(data.status)){timer=window.setTimeout(poll,1500);return}button.disabled=false;if(data.status==='completed'){fill(data.profile);const conflicts=(data.suggestions||[]).filter(item=>item.status==='review');review.hidden=conflicts.length===0;status.textContent=(data.message||'Website research completed.')+' Review the filled fields, then save.'}}async function start(){if(!valid()||website.value===lastQueued)return;lastQueued=website.value;button.disabled=true;status.textContent='Queuing website research…';try{const response=await fetch(startUrl,{method:'POST',headers:{'X-CSRF-TOKEN':token,'Content-Type':'application/json',Accept:'application/json'},credentials:'same-origin',body:JSON.stringify({website:website.value})});if(!response.ok)throw new Error();window.clearTimeout(timer);poll()}catch{button.disabled=false;status.textContent='Website research could not start. Your profile was not changed.'}}button.addEventListener('click',start);website.addEventListener('change',start)})();</script>
